lookup.entitlement:
// js
// Child leave is a shared pool: 10 weeks from 1 April 2026, 6 weeks before. Each parent defaults to half;
// an HR-approved transfer is recorded as a manual per-child allocation under the leave catalogue code.
const birth = String(get(ctx, 'event.on', ctx.as_of));
const allocated = get(ctx.subject.employment, 'child_leave_allocations.SHARED_PARENTAL_LEAVE.' + birth, null);
if (allocated != null) return Number(allocated);
return (birth >= '2026-04-01' ? 70 : 42) / 2;
